import{z as s,x as i,o as t,c as m,q as E,j as A,D as e,d as l,s as o,S as r}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"EGARCH / GJR","description":"","frontmatter":{"title":"EGARCH / GJR","date":"2026-09-07T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/egarch-gjr.md","filePath":"quant/egarch-gjr.md","lastUpdated":1791063341000}'),p={name:"quant/egarch-gjr.md"};function B(R,a,g,C,G,h){const n=i("Mermaid");return t(),m("div",null,[a[2]||(a[2]=E('<h1 id="egarch-gjr" tabindex="-1">EGARCH / GJR <a class="header-anchor" href="#egarch-gjr" aria-label="Permalink to &quot;EGARCH / GJR&quot;">​</a></h1><div class="epigraph"><p>股票的条件方差对负冲击的反应强于对正冲击；把符号放进方差方程，不必牺牲正性，也能写出这条杠杆通道。</p><footer>—— Nelson, Conditional Heteroskedasticity in Asset Returns: A New Approach, Econometrica 1991；Glosten, Jagannathan and Runkle, Journal of Finance 1993</footer></div><p><a href="/quant/garch">上一课</a>把 ARCH 收成 GARCH(1,1)，平稳性要求 \\(\\alpha+\\beta\\lt 1\\)，并点名对称 GARCH 不解释杠杆效应。缺口就是非对称：股票指数的波动在下跌后升得更猛。Nelson 的 EGARCH 在对数方差上同时放入冲击大小与符号；GJR 在水平平方上为负残差加额外权重。本课写新闻冲击曲线，并不识别财务杠杆与波动反馈。不重推 GARCH(1,1) 的 \\(\\omega,\\alpha,\\beta\\)。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>设 \\(z_t=\\varepsilon_t/\\sigma_t\\)。对称 GARCH 里 \\(\\varepsilon_{t-1}^2\\) 进入 \\(\\sigma_t^2\\)，符号消失。经验上，对股票，\\(\\mathrm{Corr}(r_t,RV_{t+1})\\) 为负，新闻冲击曲线（把 \\(z\\) 映到下一期方差）在负半轴更陡。若忽略非对称，下跌后的 \\(\\sigma_t\\) 偏低，VaR 与期权对冲会在最需要的一侧失准；上涨后的方差可能被高估。问题是在保持方差为正、过程平稳的前提下，让新闻冲击曲线不对称，并估计不对称有多强。</p><p><span class="marginnote">术语翻译：「杠杆效应」指坏消息推高波动比好消息更猛。直觉上，股价下跌让负债相对权益变贵（财务杠杆升高），股东承担的风险被放大，波动随之上升——不过模型拟合的只是这条曲线的形状，并不证明因果就来自杠杆。</span></p><p>Nelson 的 EGARCH(1,1) 典型形式为</p> \\[\\log\\sigma_t^2=\\omega+\\beta\\log\\sigma_{t-1}^2+\\alpha\\bigl(|z_{t-1}|-E|z_{t-1}|\\bigr)+\\gamma z_{t-1}. \\]<p>\\(\\gamma\\lt 0\\) 时负 \\(z\\) 抬高下一期对数方差。对数保证 \\(\\sigma_t^2\\gt 0\\)，不必对 \\(\\alpha,\\beta\\) 做非负约束。GJR-GARCH 为</p> \\[\\sigma_t^2=\\omega+\\bigl(\\alpha+\\gamma\\mathbf{1}_{\\{\\varepsilon_{t-1}\\lt 0\\}}\\bigr)\\varepsilon_{t-1}^2+\\beta\\sigma_{t-1}^2. \\]<p>\\(\\gamma\\gt 0\\) 对应股票上的杠杆效应。Zakoian 的 TARCH 用绝对值而非平方，同一家族。</p><h3 id="杠杆效应与波动反馈不是同一条因果" tabindex="-1">杠杆效应与波动反馈不是同一条因果 <a class="header-anchor" href="#杠杆效应与波动反馈不是同一条因果" aria-label="Permalink to &quot;杠杆效应与波动反馈不是同一条因果&quot;">​</a></h3><p>杠杆假说：价格跌 → 财务杠杆升 → 未来波动升。波动反馈（Campbell–Hentschel）：预期波动升 → 要求收益升 → 当期价格跌。两者都产生负的收益–波动相关，但时点不同。EGARCH/GJR 是简化式：它们拟合新闻冲击曲线，并不识别是杠杆还是反馈。用日频模型去「证明」公司财务杠杆，对象错了；要用期权或高频连续时间模型，才更接近识别。简化式对风控仍然有用：它把不对称写进 \\(\\sigma_{t|t-1}\\)。</p><p><span class="marginnote">商品与汇率上 \\(\\gamma\\) 的符号可以反转或接近零。把股票上估出来的 EGARCH 参数直接套到商品账簿，是把一种市场的新闻冲击曲线当成物理常数。分资产估计，再决定要不要在风险模型里共用非对称。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><strong>估计。</strong> 仍用条件（准）极大似然。EGARCH 无正性约束，优化更自由，但 \\(\\log\\sigma^2\\) 在极端 \\(z\\) 下可以跑得很远，数值要裁剪创新或用稳健 \\(z\\) 分布。GJR 保持水平方程，约束 \\(\\omega\\gt 0\\)，\\(\\alpha\\ge 0\\)，\\(\\alpha+\\gamma\\ge 0\\)，\\(\\beta\\ge 0\\)，平稳性涉及非对称下的期望系数，不是简单的 \\(\\alpha+\\beta\\lt 1\\)。创新用高斯或 t；股票上 t 或 GED（Nelson 原文用 GED）更常见。</p><p><strong>新闻冲击曲线。</strong> 估计后画出 \\(z\\mapsto\\sigma_{t}^2(z)\\)（其余固定在稳态）。比较对称 GARCH、EGARCH、GJR 在 \\(z=-2\\) 与 \\(z=+2\\) 处的高度。样本外用 QLIKE、VaR 违反率、以及下跌日后的预测误差，而不是只看样本内似然——非对称多一个参数，样本内几乎总会赢。</p><p><strong>与均值的联合。</strong> GJR 原文关心的是股票超额收益与波动的关系：方差进入均值（GARCH-M）时，非对称会改变风险回报的估计。工程上若只做风控，均值保持常数即可；若要用 \\(\\sigma_t\\) 当时变风险价格，必须声明是简化式，且对「波动升则期望收益升」的检验极弱、样本敏感。</p><h3 id="诊断-符号相关-不只是平方-acf" tabindex="-1">诊断：符号相关，不只是平方 ACF <a class="header-anchor" href="#诊断-符号相关-不只是平方-acf" aria-label="Permalink to &quot;诊断：符号相关，不只是平方 ACF&quot;">​</a></h3><p>对称 GARCH 抽干平方 ACF 之后，标准化残差与滞后平方仍可能有相关（负收益预示高未来方差）。这是非对称的指纹。Engle–Ng 的符号偏检验、负负偏检验，就是在问这条曲线要不要弯。通过平方 Ljung–Box 但没做符号检验，就宣布 GARCH(1,1) 足够，会把杠杆效应剩在尾部。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>EGARCH 把冲击拆成大小与方向：绝对值项吸收对称的 ARCH 效应，符号项吸收杠杆。对数域上加总，等价于方差上的乘性冲击，极端日不会像水平 GARCH 那样把 \\(\\sigma^2\\) 加出一个巨大的加法项——但指数回来后仍然可以很大。GJR 更直：负日的 \\(\\varepsilon^2\\) 多乘 \\(\\gamma\\)，是加法非对称。两种机制在中等冲击上往往难分，在极端负日上 EGARCH 的乘性与 GJR 的加法会分叉；样本外哪一个好，随市场与损失而定。</p><p><span class="marginnote">数字实例：GJR 里取 \\(\\alpha=0.05\\)、\\(\\gamma=0.05\\)。昨日 +2 个标准差的正冲击给方差加 \\(0.05\\times 4=0.20\\)；同样大小的负冲击加 \\((0.05+0.05)\\times 4=0.40\\)，恰好翻倍——同幅度下跌对明天方差的影响是上涨的两倍，这就是新闻冲击曲线的弯。</span></p>',23)),(t(),A(r,null,{default:e(()=>[o(n,{id:"mermaid-63",class:"mermaid",graph:"flowchart%20TD%0A%20%20Y%5B%22%E6%98%A8%E6%97%A5%E5%90%8C%E6%A0%B7%E5%A4%A7%E5%B0%8F%E7%9A%84%E5%86%B2%E5%87%BB%20z%20%3D%20%C2%B12%22%5D%20--%3E%20SQ%7B%22%E6%A8%A1%E5%9E%8B%E7%9C%8B%E7%AC%A6%E5%8F%B7%E5%90%97%3F%22%7D%0A%20%20SQ%20--%20%22%E5%AF%B9%E7%A7%B0%20GARCH%3A%20%E5%8F%AA%E7%9C%8B%20z%C2%B2%22%20--%3E%20EQ%5B%22%E4%B8%A4%E8%BE%B9%E4%B8%80%E6%A0%B7%3A%20%E4%B8%8B%E4%B8%80%E6%9C%9F%E6%96%B9%E5%B7%AE%E7%9B%B8%E5%90%8C%22%5D%0A%20%20SQ%20--%20%22EGARCH%20%2F%20GJR%3A%20%E5%8A%A0%E7%AC%A6%E5%8F%B7%E9%A1%B9%22%20--%3E%20ASY%5B%22%E8%B4%9F%E5%86%B2%E5%87%BB%E9%A2%9D%E5%A4%96%E6%8A%AC%E5%8D%87%3A%20%E8%B4%9F%E5%8D%8A%E8%BD%B4%E6%9B%B4%E9%99%A1%22%5D%0A%20%20EQ%20--%3E%20RISK1%5B%22VaR%20%E4%B8%8B%E8%B7%8C%E4%BE%A7%E5%81%8F%E4%BD%8E%3A%20%E6%9C%80%E9%9C%80%E8%A6%81%E6%97%B6%E5%A4%B1%E5%87%86%22%5D%0A%20%20ASY%20--%3E%20RISK2%5B%22%E4%B8%8B%E8%B7%8C%E4%BE%A7%20VaR%20%E4%B8%8E%E5%AF%B9%E5%86%B2%E6%89%8D%E5%AF%B9%E5%BE%97%E4%B8%8A%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E('<p>持续性仍然由对数自回归系数（EGARCH 的 \\(\\beta\\)）或 GJR 的 \\(\\beta\\) 加平均 ARCH 系数决定。非对称不自动等于更长记忆。危机年会同时抬高持续性估计与 \\(\\gamma\\)：一次持续下跌既像杠杆，也像水平突变。分段样本或允许方差水平切换，能避免把一次 2008 写成永远更大的 \\(\\gamma\\)。</p><p><span class="marginnote">Nelson 强调 EGARCH 可对 \\(z\\) 的正负施加不同的指数衰减，且对数保证正性。正性在 GJR 里靠约束，在 EGARCH 里靠变换。变换不是免费：对 \\(\\log\\sigma^2\\) 无偏的预测，变回 \\(\\sigma^2\\) 要 Jensen 项；多步预测 EGARCH 通常靠模拟。</span></p><h3 id="高频杠杆项是同一非对称的另一分辨率" tabindex="-1">高频杠杆项是同一非对称的另一分辨率 <a class="header-anchor" href="#高频杠杆项是同一非对称的另一分辨率" aria-label="Permalink to &quot;高频杠杆项是同一非对称的另一分辨率&quot;">​</a></h3><p>RV 对昨日负收益回归，系数常为负，HAR 可加杠杆。那是已实现测度上的简化式，信息集更富，但仍不识别财务杠杆。日频 EGARCH 与带杠杆的 HAR 应互相校准：若高频里几乎没有非对称、日频 \\(\\gamma\\) 很大，可能是隔夜跳在作怪，应拆开隔夜与日内，见 <a href="/quant/calendar-overnight">日历效应</a>。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>非对称在个股上比指数上噪：个股特质跳会把 \\(\\gamma\\) 打飞。风险模型更常对指数、行业、因子组合估 EGARCH/GJR，个股用映射。EGARCH 多步预测与矩没有 GARCH(1,1) 那么干净；若产品只需要一步 VaR，两者都可用；若需要解析的多期方差，GJR 或带杠杆的 GARCH 更省事。</p><p>不要把 \\(\\gamma\\) 显著当成可交易的「跌了就做多波动」。那是条件方差的拟合，执行还要方差风险溢价与成本。不要在对称 GARCH 与 EGARCH 之间用全样本 AIC 选完再报告唯一模型的 t 值。预指定：股票指数用非对称，汇率用对称，作为默认，其余当稳健性。正性约束在 GJR 上可能顶住（\\(\\alpha=0\\)，\\(\\gamma\\gt 0\\)），含义是「只有下跌日更新方差」，应报告，而不是当作优化失败。</p><p><span class="marginnote">常见误区：把 \\(\\gamma\\) 显著当成「跌了就做多波动」的交易信号。\\(\\gamma\\) 只是条件方差方程的拟合参数；能不能交易还要过方差风险溢价与执行成本这一关，而这一关多数时候比估计本身更难过。</span></p><p><span class="marginnote">新闻冲击曲线在 \\(z\\) 的两端样本很少。\\(\\gamma\\) 往往被少数极端日识别。估计应检查删掉最大的一两个负收益后 \\(\\gamma\\) 是否还在。若消失，模型是在拟合跳跃，不是稳定的杠杆通道——跳跃应单独建模或用稳健损失。</span></p>',9)),(t(),A(r,null,{default:e(()=>[o(n,{id:"mermaid-91",class:"mermaid",graph:"flowchart%20TD%0A%20%20Z%5B%22%E6%A0%87%E5%87%86%E5%8C%96%E5%86%B2%E5%87%BB%20z_%7Bt-1%7D%22%5D%20--%3E%20MAG%5B%22%E5%A4%A7%E5%B0%8F%20%7Cz%7C%22%5D%0A%20%20Z%20--%3E%20SGN%5B%22%E7%AC%A6%E5%8F%B7%20z%20%E6%88%96%201_%7B%CE%B5%EF%BC%9C0%7D%22%5D%0A%20%20MAG%20--%3E%20EG%5B%22EGARCH%3A%20%E8%BF%9B%E5%85%A5%20log%20%CF%83%C2%B2%22%5D%0A%20%20SGN%20--%3E%20EG%0A%20%20MAG%20--%3E%20GJR%5B%22GJR%3A%20%E8%B4%9F%E6%97%A5%E6%94%BE%E5%A4%A7%20%CE%B5%C2%B2%22%5D%0A%20%20SGN%20--%3E%20GJR%0A%20%20EG%20--%3E%20SIG%5B%22%CF%83%C2%B2_t%20%E9%9D%9E%E5%AF%B9%E7%A7%B0%22%5D%0A%20%20GJR%20--%3E%20SIG%0A%20%20SIG%20--%3E%20VAR%5B%22%E4%B8%80%E6%AD%A5%20VaR%20%2F%20%E5%AF%B9%E5%86%B2%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[l(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=E('<h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Nelson 的 EGARCH 在对数方差中同时放入冲击大小与符号；GJR 在水平 GARCH 上为负残差加额外权重。</li><li>两者拟合新闻冲击曲线，并不识别财务杠杆与波动反馈。</li><li>符号偏检验能发现对称 GARCH 抽不干的非对称；样本外应用 QLIKE 与下跌日误差，而不是只比样本内似然。</li><li>个股 \\(\\gamma\\) 噪、指数更稳；多步预测 EGARCH 常需模拟，GJR 更贴近水平 GARCH 的工程。</li><li>极端日可以单独识别 \\(\\gamma\\)；应做删除诊断，以免把跳跃写成永恒杠杆。</li><li>出处：Nelson, <em>Conditional Heteroskedasticity in Asset Returns: A New Approach</em>, Econometrica, 1991；Glosten, Jagannathan and Runkle, <em>On the Relation between the Expected Value and the Volatility of the Nominal Excess Return on Stocks</em>, Journal of Finance, 1993。</li></ul>',2))])}const c=s(p,[["render",B]]);export{_ as __pageData,c as default};
